// stateOverEmbedded is StateMethods under the name of the field that
// stateOver embeds.
type stateOverEmbedded = StateMethods

// stateOver is a subject of State whose callables call spend and return
// their zero results. The planted defect of a ceiling passes a spend that
// exceeds the ceiling.
type stateOver struct {
	stateOverEmbedded
	spend func()
}

